package com.companages.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="notifications") public class Notification {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) private User user; @ManyToOne(fetch=FetchType.LAZY) private Organization organization; @Column(nullable=false) private String type; @Column(nullable=false,length=180) private String title; @Column(nullable=false,length=1000) private String message; @Column(length=500) private String link; private Instant readAt; @Column(nullable=false,updatable=false) private Instant createdAt; @PrePersist void create(){createdAt=Instant.now();}
 public Long getId(){return id;} public User getUser(){return user;} public void setUser(User v){user=v;} public Organization getOrganization(){return organization;} public void setOrganization(Organization v){organization=v;} public String getType(){return type;} public void setType(String v){type=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public String getLink(){return link;} public void setLink(String v){link=v;} public Instant getReadAt(){return readAt;} public void setReadAt(Instant v){readAt=v;} public Instant getCreatedAt(){return createdAt;}
}
